#!/usr/bin/env python3
"""Собирает data/points.json экскурсии «Храм исповедников в Поведниках». Все факты — из открытых источников (см. SOURCES.md).
Авторы и лицензии фото берутся из tools/commons_meta.json (выгрузка Викисклада), здесь только подписи и фокус."""
import json
from pathlib import Path
B = Path(__file__).resolve().parent.parent
meta = json.loads((B / "tools" / "commons_meta.json").read_text(encoding="utf-8"))

def commons(local):
    t = meta[local]["title"].replace(" ", "_")
    return "https://commons.wikimedia.org/wiki/" + t.replace("?", "%3F").replace("#", "%23")

LIC = {"Public domain": "Общественное достояние", "CC BY-SA 4.0": "CC BY-SA 4.0", "CC BY-SA 3.0": "CC BY-SA 3.0", "CC BY-SA 2.0": "CC BY-SA 2.0", "CC BY 3.0": "CC BY 3.0", "CC0": "CC0 1.0"}
def lic(local): return LIC[meta[local]["license"]]
def yr(local):
    if local in YEARS: return YEARS[local]
    d = meta[local]["date"]
    import re
    return re.search(r"(19|20)\d\d", d).group(0)
def art(local): return AUTHORS.get(local) or meta[local]["artist"]


AUTHORS = {"then/canal-1932-37-prisoners.jpg": "автор не указан (на Викискладе: Unknown author)"}
YEARS = {"then/canal-1932-37-prisoners.jpg": "1932–1937"}

def old(local, title, rights, stand, focal=None):
    d = {"src": "img/" + local, "title": title, "year": yr(local), "author": art(local),
         "rights": rights, "stand": stand, "license": lic(local), "commons": commons(local), "remote": None, "viewpoint": None}
    if focal: d["focal"] = focal
    return d

def modern(local, title, stand, focal=None, rights="Современная фотография. Видео и снимки с водяными знаками не используются."):
    d = {"src": "img/" + local, "title": title, "year": yr(local), "author": art(local), "license": lic(local),
         "rights": rights, "commons": commons(local), "stand": stand, "viewpoint": None, "modern": True, "remote": None}
    if focal: d["focal"] = focal
    return d

def hero(local, note, missing, focal):
    return {"src": "img/" + local, "remote": None, "year": yr(local), "author": art(local), "license": lic(local),
            "commons": commons(local), "note": note, "missingThen": missing, "focal": focal}

